
'use client';

import type { z } from 'zod';
import React, { useState, useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { getPersonalizedGadgetRecommendations } from '@/ai/flows/personalized-gadget-recommendations';
import { Button } from '@/components/ui/button';
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Slider } from '@/components/ui/slider';
import { useToast } from '@/hooks/use-toast';
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from '@/components/ui/form';
import {
  GadgetRecommendation,
  studentProfileSchema,
} from '@/lib/types';
import { RecommendationList } from '@/components/recommendation-list';
import { AppHeader } from '@/components/app-header';
import { Gem } from 'lucide-react';
import { useRouter, useSearchParams } from 'next/navigation';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { LaptopList } from '@/components/laptop-list';
import { laptopData } from '@/lib/laptop-data';
import { MobileList } from '@/components/mobile-list';
import { mobileData } from '@/lib/mobile-data';

const academicStreams = [
  'Engineering',
  'Arts',
  'Medicine',
  'Business',
  'Science',
  'Law',
];
const usageTypes = ['Studying', 'Coding', 'Design', 'Gaming', 'Entertainment'];

function Finder() {
  const searchParams = useSearchParams();
  const router = useRouter();
  const [studentId, setStudentId] = useState('');
  const [recommendations, setRecommendations] = useState<
    GadgetRecommendation[]
  >([]);
  const [isLoading, setIsLoading] = useState(false);
  const { toast } = useToast();

  useEffect(() => {
    const id = searchParams.get('studentId');
    if (id) {
      setStudentId(id);
      form.setValue('studentId', id);
    } else {
      router.push('/login');
    }
  }, [searchParams, router]);

  const form = useForm<z.infer<typeof studentProfileSchema>>({
    resolver: zodResolver(studentProfileSchema),
    defaultValues: {
      academicStream: '',
      budget: 500,
      usageType: '',
      studentId: '',
    },
  });

  async function onSubmit(values: z.infer<typeof studentProfileSchema>) {
    setIsLoading(true);
    setRecommendations([]);
    try {
      const result = await getPersonalizedGadgetRecommendations({
        studentProfile: {
          ...values,
          studentIdLoginInfo: values.studentId,
        },
      });
      setRecommendations(result.recommendations);
    } catch (error) {
      console.error('Error getting recommendations:', error);
      toast({
        variant: 'destructive',
        title: 'Error',
        description:
          'Failed to generate recommendations. Please try again later.',
      });
    } finally {
      setIsLoading(false);
    }
  }

  if (!studentId) {
    return (
      <div className="flex min-h-screen w-full flex-col items-center justify-center bg-background p-4">
        <p>Loading...</p>
      </div>
    );
  }


  return (
    <div className="flex min-h-screen flex-col">
      <AppHeader studentId={studentId} onLogout={() => router.push('/login')} />
      <main className="container mx-auto flex-1 px-4 py-8">
        <Tabs defaultValue="recommendations" className="w-full">
          <TabsList className="grid w-full grid-cols-5">
            <TabsTrigger value="recommendations">Recommendations</TabsTrigger>
            <TabsTrigger value="laptops">Laptops</TabsTrigger>
            <TabsTrigger value="mobiles">Mobile</TabsTrigger>
            <TabsTrigger value="accessories">Accessories</TabsTrigger>
            <TabsTrigger value="deals">Deals</TabsTrigger>
          </TabsList>
          <TabsContent value="recommendations">
            <div className="mx-auto grid max-w-5xl gap-8 py-4">
              <Card className="overflow-hidden">
                <CardHeader>
                  <CardTitle>Your Profile</CardTitle>
                  <CardDescription>
                    Tell us about yourself to get personalized recommendations.
                  </CardDescription>
                </CardHeader>
                <CardContent>
                  <Form {...form}>
                    <form
                      onSubmit={form.handleSubmit(onSubmit)}
                      className="space-y-8"
                    >
                      <div className="grid grid-cols-1 gap-6 md:grid-cols-2">
                        <FormField
                          control={form.control}
                          name="academicStream"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>Academic Stream</FormLabel>
                              <Select
                                onValueChange={field.onChange}
                                defaultValue={field.value}
                              >
                                <FormControl>
                                  <SelectTrigger>
                                    <SelectValue placeholder="Select your stream" />
                                  </SelectTrigger>
                                </FormControl>
                                <SelectContent>
                                  {academicStreams.map((stream) => (
                                    <SelectItem key={stream} value={stream}>
                                      {stream}
                                    </SelectItem>
                                  ))}
                                </SelectContent>
                              </Select>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                        <FormField
                          control={form.control}
                          name="usageType"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>Primary Usage</FormLabel>
                              <Select
                                onValueChange={field.onChange}
                                defaultValue={field.value}
                              >
                                <FormControl>
                                  <SelectTrigger>
                                    <SelectValue placeholder="Select primary usage" />
                                  </SelectTrigger>
                                </FormControl>
                                <SelectContent>
                                  {usageTypes.map((use) => (
                                    <SelectItem key={use} value={use}>
                                      {use}
                                    </SelectItem>
                                  ))}
                                </SelectContent>
                              </Select>
                              <FormMessage />
                            </FormItem>
                          )}
                        />
                      </div>

                      <FormField
                        control={form.control}
                        name="budget"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel>
                              Budget: ${field.value.toLocaleString()}
                            </FormLabel>
                            <FormControl>
                              <Slider
                                min={100}
                                max={3000}
                                step={50}
                                onValueChange={(value) => field.onChange(value[0])}
                                defaultValue={[field.value]}
                              />
                            </FormControl>
                          </FormItem>
                        )}
                      />

                      <Button type="submit" disabled={isLoading} size="lg">
                        <Gem className="mr-2 h-4 w-4" />
                        {isLoading
                          ? 'Analyzing...'
                          : 'Generate Recommendations'}
                      </Button>
                    </form>
                  </Form>
                </CardContent>
              </Card>

              <RecommendationList
                recommendations={recommendations}
                isLoading={isLoading}
              />
            </div>
          </TabsContent>
          <TabsContent value="laptops">
            <Card>
              <CardHeader>
                <CardTitle>Laptops</CardTitle>
                <CardDescription>
                  Powerful laptops for every student.
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-2">
                <LaptopList laptops={laptopData.laptops} />
              </CardContent>
            </Card>
          </TabsContent>
          <TabsContent value="mobiles">
            <Card>
              <CardHeader>
                <CardTitle>Mobile Devices</CardTitle>
                <CardDescription>
                  Tablets and smartphones for learning on the go.
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-2">
                 <MobileList mobiles={mobileData.mobiles} />
              </CardContent>
            </Card>
          </TabsContent>
          <TabsContent value="accessories">
            <Card>
              <CardHeader>
                <CardTitle>Accessories</CardTitle>
                <CardDescription>
                  Essential accessories to complete your setup.
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-2">
                <iframe
                  src="https://www.rtings.com/"
                  className="w-full h-[800px] border-0"
                  title="Accessories from RTINGS.com"
                ></iframe>
              </CardContent>
            </Card>
          </TabsContent>
          <TabsContent value="deals">
            <Card>
              <CardHeader>
                <CardTitle>Deals</CardTitle>
                <CardDescription>
                  Hot deals on popular student gadgets.
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-2">
                <iframe
                  src="https://freeforstudents.org/in"
                  className="w-full h-[800px] border-0"
                  title="Deals from freeforstudents.org"
                ></iframe>
              </CardContent>
            </Card>
          </TabsContent>
        </Tabs>
      </main>
    </div>
  );
}

export default function FinderPage() {
  return (
    <React.Suspense fallback={<div>Loading...</div>}>
      <Finder />
    </React.Suspense>
  )
}
